INSERT INTO `chat_messages` (`id`, `room_id`, `sender_gmail`, `message`, `message_type`, `created_at`, `is_read`) VALUES
(495, 37, 'AdminDev@gmail.com', 'Perhatian! Segera Selesaikan Pendaftaran Pascasarjana UNJ Gelombang I Tahun 2025\n\nHalo, Calon Mahasiswa Pascasarjana UNJ! Kami melihat bahwa Anda telah mendaftar di Pascasarjana UNJ, tetapi belum menyelesaikan tahapan selanjutnya. Pastikan Anda segera menyelesaikan pembayaran dan melengkapi proses administrasi agar tidak kehilangan kesempatan untuk bergabung di UNJ!\n\nJadwal Penting yang Harus Segera Anda Selesaikan:\n✅ Batas Akhir Pendaftaran: 10 Maret 2025\n✅ Seleksi Tulis: 15 Maret 2025\n✅ Seleksi Wawancara: 15 Maret 2025\n✅ Pengumuman Hasil Seleksi: 20 Maret 2025\n✅ Daftar Ulang: 21 Maret - 11 April 2025\n✅ Matrikulasi: 7 Juli - 22 Agustus 2025\n\n🔗 Selesaikan Pendaftaran Anda Sekarang di: https://pendaftaran.unj.ac.id/pascasarjana/\n\n⚠ Segera lakukan pembayaran agar status pendaftaran Anda aktif dan dapat mengikuti tahapan seleksi berikutnya! Jangan sampai pendaftaran Anda hangus hanya karena lupa menyelesaikan pembayaran!\n\n💡 Keuntungan menyelesaikan pendaftaran lebih awal:\n✅ Menghindari risiko sistem sibuk menjelang batas akhir\n✅ Memastikan data Anda terverifikasi tanpa kendala\n✅ Bisa fokus mempersiapkan diri untuk seleksi tulis dan wawancara\n\nJangan tunda lagi! Segera selesaikan pendaftaran Anda dan pastikan tempat Anda di Pascasarjana UNJ! 🚀', 'text', '2026-10-25 09:11:25', 1);
INSERT INTO `chat_messages` (`id`, `room_id`, `sender_gmail`, `message`, `message_type`, `created_at`, `is_read`) VALUES
(496, 37, 'AdminDev@gmail.com', '{\"files\":[{\"name\":\"CuriculumVitae Maulana Syafikh Alkhudri.pdf\",\"data\":\"data:application/pdf;base64,\",\"type\":\"file\"},{\"name\":\"KRS_124__NIM_1512625004_20260306185953.pdf\",\"data\":\"data:application/pdf;base64,\",\"type\":\"file\"},{\"name\":\"user research (2).png\",\"data\":\"data:image/png;base64,\",\"type\":\"image\"},{\"name\":\"user research (1).png\",\"data\":\"data:image/png;base64,\",\"type\":\"image\"}],\"caption\":\"Halo kak, saat ini kami belum memiliki lini waktu pasti terkait pembukaan jalur mandiri UNJ, tetapi mengacu pada tahun 2025 kami membuka beberapa jalur mandiri. Diantaranya:\\n1. Penmaba Prestasi (penmaba.unj.ac.id/penmaba-prestasi)\\n2. Penmaba Nilai UTBK (penmaba.unj.ac.id/nilaiutbk)\\n3. Penmaba Disabilitas (penmaba.unj.ac.id/penmaba-jalur-disabilitas)\\n4. Penmaba Ujian Tulis di Kampus (https://penmaba.unj.ac.id/mandiri-ujian-tulis/)\\n5. Penmaba Ujian Tulis di Kediaman (https://penmaba.unj.ac.id/penmaba-dikediaman/)\\n6. Penmaba Rapor (https://penmaba.unj.ac.id/rapor/)\\n\\nCatatan Tambahan:\\nefshfsiuhfsehfsichdziofedojdw\"}', 'multi_file', '2026-10-26 03:33:33', 0);

